// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address caddress, address[] memory _tos, uint[] memory v) public {
        vm.assume(_tos.length > 0);
        vm.assume(_tos.length == v.length);

        // Deploy a helper that always returns success for the low-level call
        SuccessCallee sc = new SuccessCallee();

        (bool pSuccess, bytes memory pData) = address(c).call(
            abi.encodeWithSignature("transfer(address,address,address[],uint256[])", from, address(sc), _tos, v)
        );
        require(pSuccess, "P transfer reverted");
        bool pResult = abi.decode(pData, (bool));

        assertTrue(pResult);
    }
}

contract SuccessCallee {
    function transferFrom(address from, address to, uint256 amount) external pure returns (bool) {
        return true;
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address caddress, address[] memory _tos, uint256[] memory v) public {
        vm.assume(_tos.length > 0);
        vm.assume(_tos.length == v.length);
        vm.assume(caddress != address(this));
        vm.assume(caddress != address(c));
        vm.assume(caddress.code.length == 0);
        bool ok;
        try c.transfer(from, caddress, _tos, v) returns (bool result) {
            ok = result;
        } catch { return; }
        assertTrue(ok);
    }
}
